  static const fb.Reader<OIL> reader = _OILReader();

  final fb.BufferContext _bc;
  final int _bcOffset;

  ///  Provider of the crosswalk, e.g. "vimpel".
  String? get PROVIDER => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 4);
  ///  Kind of crosswalk, e.g. "datefirst".
  String? get KIND => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 6);
  ///  Namespace of every LEFT identifier, when uniform.
  String? get LEFT_NAMESPACE => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 8);
  String? get leftNamespace => LEFT_NAMESPACE;
  ///  Namespace of every RIGHT identifier, when uniform.
  String? get RIGHT_NAMESPACE => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 10);
  String? get rightNamespace => RIGHT_NAMESPACE;
  ///  Header line of the source file as printed, e.g.
  ///  "Nvym t_det_v Nnor t_det_n".
  String? get HEADER => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 12);
  ///  SHA-256 hex digest of the source edition (the RECORD_ID of its links).
  String? get SHA256 => const fb.StringReader().vTableGetNullable(_bc, _bcOffset, 14);
  ///  Size of the source edition, bytes.
  int get BYTES => const fb.Uint64Reader().vTableGet(_bc, _bcOffset, 16, 0);
  ///  Data rows read (header excluded).
  int get ROWS => const fb.Uint32Reader().vTableGet(_bc, _bcOffset, 18, 0);
  ///  Rows that repeated an earlier pair.
  int get DUPLICATE_LINES => const fb.Uint32Reader().vTableGet(_bc, _bcOffset, 20, 0);
  int get duplicateLines => DUPLICATE_LINES;
  ///  Distinct links (LINKS length).
  int get LINK_COUNT => const fb.Uint32Reader().vTableGet(_bc, _bcOffset, 22, 0);
  int get linkCount => LINK_COUNT;
  ///  Links in one-to-one groups.
  int get CLEAN_COUNT => const fb.Uint32Reader().vTableGet(_bc, _bcOffset, 24, 0);
  int get cleanCount => CLEAN_COUNT;
  ///  Links in groups that are not one-to-one.
  int get AMBIGUOUS_COUNT => const fb.Uint32Reader().vTableGet(_bc, _bcOffset, 26, 0);
  int get ambiguousCount => AMBIGUOUS_COUNT;
  ///  Distinct left identifiers.
  int get LEFT_ID_COUNT => const fb.Uint32Reader().vTableGet(_bc, _bcOffset, 28, 0);
  int get leftIdCount => LEFT_ID_COUNT;
  ///  Distinct right identifiers.
  int get RIGHT_ID_COUNT => const fb.Uint32Reader().vTableGet(_bc, _bcOffset, 30, 0);
  int get rightIdCount => RIGHT_ID_COUNT;
  ///  Links whose repeated declarations give different dates.
  int get DATES_DIFFER_COUNT => const fb.Uint32Reader().vTableGet(_bc, _bcOffset, 32, 0);
  int get datesDifferCount => DATES_DIFFER_COUNT;
  ///  Links with a first-detection date that is not a valid date.
  int get UNREADABLE_DATE_COUNT => const fb.Uint32Reader().vTableGet(_bc, _bcOffset, 34, 0);
  int get unreadableDateCount => UNREADABLE_DATE_COUNT;
  List<OILLink>? get LINKS => const fb.ListReader<OILLink>(OILLink.reader).vTableGetNullable(_bc, _bcOffset, 36);
  List<OILConflict>? get CONFLICTS => const fb.ListReader<OILConflict>(OILConflict.reader).vTableGetNullable(_bc, _bcOffset, 38);
