  int get GENERATED_AT_MS => const fb.Int64Reader().vTableGet(_bc, _bcOffset, 40, 0);
  int get generatedAtMs => GENERATED_AT_MS;

  @override
  String toString() {
    return 'OIL{PROVIDER: ${PROVIDER}, KIND: ${KIND}, leftNamespace: ${leftNamespace}, rightNamespace: ${rightNamespace}, HEADER: ${HEADER}, SHA256: ${SHA256}, BYTES: ${BYTES}, ROWS: ${ROWS}, duplicateLines: ${duplicateLines}, linkCount: ${linkCount}, cleanCount: ${cleanCount}, ambiguousCount: ${ambiguousCount}, leftIdCount: ${leftIdCount}, rightIdCount: ${rightIdCount}, datesDifferCount: ${datesDifferCount}, unreadableDateCount: ${unreadableDateCount}, LINKS: ${LINKS}, CONFLICTS: ${CONFLICTS}, generatedAtMs: ${generatedAtMs}}';
  }
}

class _OILReader extends fb.TableReader<OIL> {
  const _OILReader();

  @override
  OIL createObject(fb.BufferContext bc, int offset) =>
    OIL._(bc, offset);
}

class OILBuilder {
  OILBuilder(this.fbBuilder);

  final fb.Builder fbBuilder;

  void begin() {
    fbBuilder.startTable(19);
  }

  int addProviderOffset(int? offset) {
    fbBuilder.addOffset(0, offset);
    return fbBuilder.offset;
  }
  int addKindOffset(int? offset) {
    fbBuilder.addOffset(1, offset);
    return fbBuilder.offset;
  }
  int addLeftNamespaceOffset(int? offset) {
    fbBuilder.addOffset(2, offset);
    return fbBuilder.offset;
  }
  int addRightNamespaceOffset(int? offset) {
    fbBuilder.addOffset(3, offset);
    return fbBuilder.offset;
  }
  int addHeaderOffset(int? offset) {
    fbBuilder.addOffset(4, offset);
    return fbBuilder.offset;
  }
  int addSha256Offset(int? offset) {
    fbBuilder.addOffset(5, offset);
    return fbBuilder.offset;
  }
  int addBytes(int? BYTES) {
    fbBuilder.addUint64(6, BYTES);
    return fbBuilder.offset;
  }
  int addRows(int? ROWS) {
    fbBuilder.addUint32(7, ROWS);
    return fbBuilder.offset;
  }
  int addDuplicateLines(int? DUPLICATE_LINES) {
    fbBuilder.addUint32(8, DUPLICATE_LINES);
    return fbBuilder.offset;
  }
  int addLinkCount(int? LINK_COUNT) {
    fbBuilder.addUint32(9, LINK_COUNT);
    return fbBuilder.offset;
  }
  int addCleanCount(int? CLEAN_COUNT) {
    fbBuilder.addUint32(10, CLEAN_COUNT);
    return fbBuilder.offset;
  }
  int addAmbiguousCount(int? AMBIGUOUS_COUNT) {
    fbBuilder.addUint32(11, AMBIGUOUS_COUNT);
    return fbBuilder.offset;
  }
  int addLeftIdCount(int? LEFT_ID_COUNT) {
    fbBuilder.addUint32(12, LEFT_ID_COUNT);
    return fbBuilder.offset;
  }
  int addRightIdCount(int? RIGHT_ID_COUNT) {
    fbBuilder.addUint32(13, RIGHT_ID_COUNT);
    return fbBuilder.offset;
  }
  int addDatesDifferCount(int? DATES_DIFFER_COUNT) {
    fbBuilder.addUint32(14, DATES_DIFFER_COUNT);
    return fbBuilder.offset;
  }
  int addUnreadableDateCount(int? UNREADABLE_DATE_COUNT) {
    fbBuilder.addUint32(15, UNREADABLE_DATE_COUNT);
    return fbBuilder.offset;
  }
  int addLinksOffset(int? offset) {
    fbBuilder.addOffset(16, offset);
    return fbBuilder.offset;
  }
  int addConflictsOffset(int? offset) {
    fbBuilder.addOffset(17, offset);
    return fbBuilder.offset;
  }
  int addGeneratedAtMs(int? GENERATED_AT_MS) {
    fbBuilder.addInt64(18, GENERATED_AT_MS);
    return fbBuilder.offset;
  }

  int finish() {
    return fbBuilder.endTable();
  }
}

class OILObjectBuilder extends fb.ObjectBuilder {
  final String? _PROVIDER;
  final String? _KIND;
  final String? _LEFT_NAMESPACE;
  final String? _RIGHT_NAMESPACE;
  final String? _HEADER;
  final String? _SHA256;
  final int? _BYTES;
  final int? _ROWS;
  final int? _DUPLICATE_LINES;
  final int? _LINK_COUNT;
  final int? _CLEAN_COUNT;
  final int? _AMBIGUOUS_COUNT;
  final int? _LEFT_ID_COUNT;
  final int? _RIGHT_ID_COUNT;
  final int? _DATES_DIFFER_COUNT;
  final int? _UNREADABLE_DATE_COUNT;
  final List<OILLinkObjectBuilder>? _LINKS;
  final List<OILConflictObjectBuilder>? _CONFLICTS;
  final int? _GENERATED_AT_MS;

  OILObjectBuilder({
    String? PROVIDER,
    String? KIND,
    String? LEFT_NAMESPACE,
    String? leftNamespace,
    String? RIGHT_NAMESPACE,
    String? rightNamespace,
    String? HEADER,
    String? SHA256,
    int? BYTES,
    int? ROWS,
    int? DUPLICATE_LINES,
    int? duplicateLines,
    int? LINK_COUNT,
    int? linkCount,
    int? CLEAN_COUNT,
    int? cleanCount,
    int? AMBIGUOUS_COUNT,
    int? ambiguousCount,
    int? LEFT_ID_COUNT,
    int? leftIdCount,
    int? RIGHT_ID_COUNT,
    int? rightIdCount,
    int? DATES_DIFFER_COUNT,
    int? datesDifferCount,
    int? UNREADABLE_DATE_COUNT,
    int? unreadableDateCount,
    List<OILLinkObjectBuilder>? LINKS,
    List<OILConflictObjectBuilder>? CONFLICTS,
    int? GENERATED_AT_MS,
    int? generatedAtMs,
  })
      : _PROVIDER = PROVIDER,
        _KIND = KIND,
        _LEFT_NAMESPACE = leftNamespace ?? LEFT_NAMESPACE,
        _RIGHT_NAMESPACE = rightNamespace ?? RIGHT_NAMESPACE,
        _HEADER = HEADER,
        _SHA256 = SHA256,
        _BYTES = BYTES,
        _ROWS = ROWS,
        _DUPLICATE_LINES = duplicateLines ?? DUPLICATE_LINES,
        _LINK_COUNT = linkCount ?? LINK_COUNT,
        _CLEAN_COUNT = cleanCount ?? CLEAN_COUNT,
        _AMBIGUOUS_COUNT = ambiguousCount ?? AMBIGUOUS_COUNT,
        _LEFT_ID_COUNT = leftIdCount ?? LEFT_ID_COUNT,
        _RIGHT_ID_COUNT = rightIdCount ?? RIGHT_ID_COUNT,
        _DATES_DIFFER_COUNT = datesDifferCount ?? DATES_DIFFER_COUNT,
        _UNREADABLE_DATE_COUNT = unreadableDateCount ?? UNREADABLE_DATE_COUNT,
        _LINKS = LINKS,
        _CONFLICTS = CONFLICTS,
        _GENERATED_AT_MS = generatedAtMs ?? GENERATED_AT_MS;

  /// Finish building, and store into the [fbBuilder].
  @override
  int finish(fb.Builder fbBuilder) {
    final int? PROVIDEROffset = _PROVIDER == null ? null
        : fbBuilder.writeString(_PROVIDER!);
    final int? KINDOffset = _KIND == null ? null
        : fbBuilder.writeString(_KIND!);
    final int? LEFT_NAMESPACEOffset = _LEFT_NAMESPACE == null ? null
        : fbBuilder.writeString(_LEFT_NAMESPACE!);
    final int? RIGHT_NAMESPACEOffset = _RIGHT_NAMESPACE == null ? null
        : fbBuilder.writeString(_RIGHT_NAMESPACE!);
    final int? HEADEROffset = _HEADER == null ? null
        : fbBuilder.writeString(_HEADER!);
    final int? SHA256Offset = _SHA256 == null ? null
        : fbBuilder.writeString(_SHA256!);
    final int? LINKSOffset = _LINKS == null ? null
        : fbBuilder.writeList(_LINKS!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? CONFLICTSOffset = _CONFLICTS == null ? null
        : fbBuilder.writeList(_CONFLICTS!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    fbBuilder.startTable(19);
    fbBuilder.addOffset(0, PROVIDEROffset);
    fbBuilder.addOffset(1, KINDOffset);
    fbBuilder.addOffset(2, LEFT_NAMESPACEOffset);
    fbBuilder.addOffset(3, RIGHT_NAMESPACEOffset);
    fbBuilder.addOffset(4, HEADEROffset);
    fbBuilder.addOffset(5, SHA256Offset);
    fbBuilder.addUint64(6, _BYTES);
    fbBuilder.addUint32(7, _ROWS);
    fbBuilder.addUint32(8, _DUPLICATE_LINES);
    fbBuilder.addUint32(9, _LINK_COUNT);
    fbBuilder.addUint32(10, _CLEAN_COUNT);
    fbBuilder.addUint32(11, _AMBIGUOUS_COUNT);
    fbBuilder.addUint32(12, _LEFT_ID_COUNT);
    fbBuilder.addUint32(13, _RIGHT_ID_COUNT);
    fbBuilder.addUint32(14, _DATES_DIFFER_COUNT);
    fbBuilder.addUint32(15, _UNREADABLE_DATE_COUNT);
    fbBuilder.addOffset(16, LINKSOffset);
    fbBuilder.addOffset(17, CONFLICTSOffset);
    fbBuilder.addInt64(18, _GENERATED_AT_MS);
    return fbBuilder.endTable();
  }

  /// Convenience method to serialize to byte list.
  @override
  Uint8List toBytes([String? fileIdentifier]) {
    final fbBuilder = fb.Builder(deduplicateTables: false);
    fbBuilder.finish(finish(fbBuilder), fileIdentifier);
    return fbBuilder.buffer;
  }
}
